        CloudBlobClient cloudBlobClient = cloudStorageAccount.CreateCloudBlobClient();
        string strContainerName = "uploads";
        CloudBlobContainer cloudBlobContainer = cloudBlobClient.GetContainerReference(strContainerName);

        string pathPrefix = Path.GetDirectoryName(uriObj.LocalPath);// DateTime.Now.ToUniversalTime().ToString("yyyy-MM-dd") + "/";
        string[] paths = fileUrl.Split("/");
        if (paths.Length >= 2)
        {
            pathPrefix = paths[paths.Length - 2];
        }

        CloudBlobDirectory blobDirectory = cloudBlobContainer.GetDirectoryReference(pathPrefix);
        // get block blob refarence    
        CloudBlockBlob blockBlob = blobDirectory.GetBlockBlobReference(BlobName);


        // delete blob from container        
        var memStream = new MemoryStream();
        await blockBlob.DownloadRangeToStreamAsync(memStream, 0, blockBlob.StreamMinimumReadSizeInBytes);
        return memStream;

    }
